import { CustomThemeProvider } from './context/ThemeContext';

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <CustomThemeProvider>
    <BrowserRouter>
      <App />
    </BrowserRouter>
  </CustomThemeProvider>
);
